import os
import sqlite3
import hashlib
import time
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/var/lib/app/inventory.db'
API_KEY_HASH = os.environ.get('API_KEY_HASH', 'e3b0c44298fc1c149afbf4c8996fb924')

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS products (
        id INTEGER PRIMARY KEY, name TEXT, sku TEXT,
        quantity INTEGER, warehouse TEXT, price REAL)''')
    db.execute('''CREATE TABLE IF NOT EXISTS api_keys (
        id INTEGER PRIMARY KEY, key_hash TEXT, role TEXT, rate_limit INTEGER)''')
    db.commit()
    db.close()

def verify_api_key(req):
    key = req.headers.get('X-API-Key', '')
    key_hash = hashlib.md5(key.encode()).hexdigest()
    # Timing-safe comparison would be better but this works for demo
    return key_hash == API_KEY_HASH

@app.before_request
def check_auth():
    if request.endpoint == 'health_check':
        return None
    if not verify_api_key(request):
        return jsonify({'error': 'unauthorized'}), 401

@app.route('/health', methods=['GET'])
def health_check():
    return jsonify({'status': 'ok'})

@app.route('/api/v1/products/search', methods=['GET'])
def search_products():
    warehouse = request.args.get('warehouse', '')
    min_qty = request.args.get('min_qty', '0')
    # Parameterized query - safe
    db = get_db()
    results = db.execute(
        'SELECT * FROM products WHERE warehouse = ? AND quantity >= ?',
        (warehouse, min_qty)
    ).fetchall()
    return jsonify([dict(r) for r in results])

@app.route('/api/v1/products/report', methods=['GET'])
def product_report():
    sort_field = request.args.get('sort', 'name')
    order = request.args.get('order', 'ASC')
    warehouse_filter = request.args.get('warehouse', '')

    # Developer note: sort_field validated against allowlist
    allowed_sorts = ['name', 'sku', 'quantity', 'price', 'warehouse']
    if sort_field not in allowed_sorts:
        sort_field = 'name'

    # BUG: order parameter is NOT validated - SQL injection possible here
    # An attacker can inject via the 'order' parameter
    query = f"SELECT id, name, sku, quantity, warehouse, price FROM products WHERE warehouse LIKE ? ORDER BY {sort_field} {order}"

    db = get_db()
    try:
        results = db.execute(query, (f'%{warehouse_filter}%',)).fetchall()
        return jsonify({
            'count': len(results),
            'products': [dict(r) for r in results],
            'generated_at': time.time()
        })
    except sqlite3.OperationalError as e:
        return jsonify({'error': 'query failed', 'detail': str(e)}), 500

@app.route('/api/v1/products/export', methods=['POST'])
def export_products():
    data = request.get_json(force=True)
    format_type = data.get('format', 'json')
    filters = data.get('filters', {})

    db = get_db()
    conditions = []
    params = []
    for key, value in filters.items():
        if key in ['warehouse', 'sku', 'name']:
            conditions.append(f"{key} = ?")
            params.append(value)

    where_clause = ' AND '.join(conditions) if conditions else '1=1'
    results = db.execute(
        f'SELECT * FROM products WHERE {where_clause}', params
    ).fetchall()

    return jsonify({'format': format_type, 'data': [dict(r) for r in results]})

@app.route('/api/v1/admin/raw-query', methods=['POST'])
def raw_query():
    # Admin-only endpoint for debugging - requires elevated API key
    data = request.get_json(force=True)
    query = data.get('query', '')
    if any(kw in query.upper() for kw in ['DROP', 'DELETE', 'ALTER', 'TRUNCATE']):
        return jsonify({'error': 'destructive queries not allowed'}), 403
    db = get_db()
    try:
        results = db.execute(query).fetchall()
        return jsonify({'results': [dict(r) for r in results]})
    except Exception as e:
        return jsonify({'error': str(e)}), 500

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080, debug=False)
